{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "In normal subjects, verapamil absolute oral bioavailability was 22.0% after simultaneous IV/oral dosing, above the 20% threshold; verapamil shares the dimethoxyphenyl and tertiary-amine motifs with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, which contains the same dimethoxybenzene-fused ring motif as the query, has an absolute oral bioavailability of approximately 49% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxyisoquinoline-related alkaloid, has an absolute oral bioavailability of 30% in healthy volunteers, supporting high F for the dimethoxyisoquinoline-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Levosulpiride, a dimethoxy-substituted benzamide with poor and incomplete absorption, still reaches about 30% oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "In 20 normal young men, verapamil bioavailability averaged 19.4% after oral doses compared with IV, just below the 20% threshold, indicating borderline first-pass metabolism in the closest analog class.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a dimethoxyphenyl/tertiary-amine analog most similar to verapamil, whose absolute oral bioavailability is generally 22–38% in normal subjects, with only occasional values just below 20%. Additional structural relatives (valbenazine ~49%, noscapine 30%, levosulpiride ~30%) all exceed the 20% threshold. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental measurement of the query molecule's oral bioavailability.",
    "The query is not identical to any evidence molecule; structural analogy is based on shared dimethoxyphenyl/amine and fused-ring motifs.",
    "Verapamil, the closest analog, has values straddling the 20% threshold (19.4–38%), so the margin above threshold is modest."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

